//! Pairing contract and domain values.
//!
//! Pairing invitations are opaque to hosts. They may be rendered as text or a
//! QR code, but only the Rust core parses or assigns meaning to them.

mod service;

use std::fmt::Debug;

use async_trait::async_trait;
use thiserror::Error;

use crate::DeviceInfo;

pub(crate) use service::IrohPairing;

/// An opaque, versioned invitation generated by a Mist runtime.
#[derive(Clone, Debug, Eq, PartialEq, uniffi::Record)]
pub struct PairingOffer {
    /// The complete invitation payload to transfer to the other device.
    pub encoded: String,
}

/// The authenticated Iroh peer installed into the Mist runtime.
#[derive(Clone, Debug, Eq, PartialEq, uniffi::Record)]
pub struct PairedPeer {
    /// The peer's stable Iroh endpoint identity.
    pub endpoint_id: String,
    /// Device metadata received after pairing authorization succeeded.
    pub device: DeviceInfo,
}

/// A pairing operation could not be completed.
#[derive(Debug, Error, uniffi::Error)]
pub enum PairingError {
    /// The invitation was not a supported Mist pairing payload.
    #[error("invalid Mist pairing offer: {reason}")]
    InvalidOffer {
        /// Human-readable parsing failure for diagnostics.
        reason: String,
    },

    /// The invitation creator rejected the pairing token.
    #[error("the Mist pairing offer was rejected: {reason}")]
    Rejected {
        /// Human-readable rejection reason.
        reason: String,
    },

    /// The platform could not generate a secure pairing token.
    #[error("failed to generate a secure pairing token: {reason}")]
    TokenGeneration {
        /// Human-readable random-source failure.
        reason: String,
    },

    /// No active invitation exists for this runtime.
    #[error("create a pairing offer before waiting for its peer")]
    NoPendingOffer,

    /// The active invitation was cancelled.
    #[error("the Mist pairing offer was cancelled")]
    Cancelled,

    /// The peer did not follow the Mist pairing protocol.
    #[error("Mist pairing protocol failed: {reason}")]
    Protocol {
        /// Human-readable protocol failure for diagnostics.
        reason: String,
    },

    /// The runtime already belongs to a session with another peer.
    #[error("the Mist runtime is already paired with another peer")]
    AlreadyPaired,

    /// Iroh could not establish the outgoing connection.
    #[error("failed to connect to the pairing peer: {reason}")]
    Connect {
        /// Human-readable Iroh failure for diagnostics.
        reason: String,
    },

    /// An incoming Iroh connection failed during its handshake.
    #[error("failed to accept the pairing peer: {reason}")]
    Accept {
        /// Human-readable Iroh failure for diagnostics.
        reason: String,
    },

    /// The runtime closed while waiting for the invited peer.
    #[error("the Mist runtime closed before the pairing peer connected")]
    RuntimeClosed,

    /// The Rust executor used by foreign-language bindings could not run the
    /// pairing operation.
    #[error("failed to run pairing on the Mist native executor: {reason}")]
    Executor {
        /// Human-readable executor failure for diagnostics.
        reason: String,
    },
}

/// Establishes the one peer relationship owned by a [`MistRuntime`](crate::MistRuntime).
///
/// Hosts receive this interface from [`MistRuntime::pairing`](crate::MistRuntime::pairing).
/// Implementations live in Rust; UniFFI/Gobley generates the corresponding
/// Kotlin interface.
#[uniffi::export]
#[async_trait]
pub trait Pairing: Send + Sync + Debug {
    /// Creates an invitation for another device.
    ///
    /// The initiating host should transfer the returned opaque payload to the
    /// other device, then call [`wait_for_peer`](Self::wait_for_peer).
    ///
    /// # Errors
    ///
    /// Returns an error if a peer is already installed, secure randomness is
    /// unavailable, or the local pairing state cannot be updated.
    fn initiate(&self) -> Result<PairingOffer, PairingError>;

    /// Invalidates the active invitation, if any.
    fn cancel(&self);

    /// Accepts an invitation created by another Mist runtime.
    ///
    /// On success, the resulting Iroh connection becomes the runtime's one
    /// stable connection.
    async fn accept(&self, offer: PairingOffer) -> Result<PairedPeer, PairingError>;

    /// Waits for the peer holding this runtime's invitation to connect.
    ///
    /// On success, the accepted Iroh connection becomes the runtime's one
    /// stable connection.
    async fn wait_for_peer(&self) -> Result<PairedPeer, PairingError>;
}

